import urwid
import sys

# Custom characters for LCD emulation
CHECKBOX_ON = u"\u25A3"   # ⎣ (as a custom checkbox checked)
CHECKBOX_OFF = u"\u25A1"  # □ (as a custom checkbox unchecked)
RADIO_ON = u"\u25C9"      # ◉ (as a custom radio button selected)
RADIO_OFF = u"\u25CB"     # ○ (as a custom radio button unselected)
PROGRESS_CHARS = [u"\u2591", u"\u2592", u"\u2593", u"\u2588"]  # ░▒▓█
SLIDER_LEFT = u"\u25C0"   # ◀
SLIDER_RIGHT = u"\u25B6"  # ▶
SLIDER_BAR = u"\u2500"    # ─
SLIDER_KNOB = u"\u25CF"   # ●
MENU_ARROW = u"\u25B6"    # ▶

# Dummy LCD connection class
class LCDConnection:
    def __init__(self, port):
        self.port = port
    def set_brightness(self, value):
        pass
    def set_contrast(self, value):
        pass
    def set_cursor_style(self, style):
        pass
    def set_led_color(self, led, color):
        pass

# Connect to LCD using command line argument
if len(sys.argv) < 2:
    print("Usage: python demo.py <lcd_port>")
    sys.exit(1)
lcd = LCDConnection(sys.argv[1])

palette = [
    ('reversed', 'standout', ''),
    ('slider', 'light cyan', ''),
    ('slider_knob', 'light red', ''),
    ('menu', 'light green', ''),
    ('focus', 'black', 'light gray'),
    ('led_red', 'dark red', ''),
    ('led_green', 'dark green', ''),
    ('led_blue', 'dark blue', ''),
    ('led_yellow', 'yellow', ''),
    ('led_white', 'white', ''),
    ('led_off', 'black', ''),
]

def menu_button(caption, callback, user_data=None):
    button = urwid.Button([caption, " ", MENU_ARROW])
    urwid.connect_signal(button, 'click', callback, user_data)
    return urwid.AttrMap(button, 'menu', focus_map='focus')

def back_button(callback):
    button = urwid.Button("Back")
    urwid.connect_signal(button, 'click', callback)
    return urwid.AttrMap(button, 'menu', focus_map='focus')

def custom_checkbox(label, state, on_state_change):
    txt = urwid.Text([CHECKBOX_ON if state else CHECKBOX_OFF, " ", label])
    def toggle(button):
        on_state_change(not state)
    button = urwid.Button("", toggle)
    return urwid.AttrMap(urwid.Columns([('fixed', 2, txt), button]), None)

def custom_radio(label, group, state, on_state_change):
    txt = urwid.Text([RADIO_ON if state else RADIO_OFF, " ", label])
    def select(button):
        on_state_change(label)
    button = urwid.Button("", select)
    return urwid.AttrMap(urwid.Columns([('fixed', 2, txt), button]), None)

def custom_progress_bar(value, max_value=100, width=16):
    n_chars = int((value / max_value) * width)
    bar = ""
    for i in range(width):
        if i < n_chars:
            bar += PROGRESS_CHARS[-1]
        else:
            bar += PROGRESS_CHARS[0]
    return urwid.Text(bar)

class CustomSlider(urwid.WidgetWrap):
    def __init__(self, label, min_value, max_value, value, on_change):
        self.label = label
        self.min = min_value
        self.max = max_value
        self.value = value
        self.on_change = on_change
        self.width = 16
        self._w = self._build()
    def _build(self):
        pos = int((self.value - self.min) / (self.max - self.min) * (self.width - 1))
        bar = SLIDER_LEFT
        for i in range(self.width):
            if i == pos:
                bar += ('slider_knob', SLIDER_KNOB)
            else:
                bar += ('slider', SLIDER_BAR)
        bar += SLIDER_RIGHT
        return urwid.Columns([
            ('fixed', 12, urwid.Text(self.label)),
            urwid.Text(bar),
            ('fixed', 4, urwid.Text(str(self.value)))
        ])
    def keypress(self, size, key):
        if key in ('left', 'h'):
            if self.value > self.min:
                self.value -= 1
                self._w = self._build()
                self.on_change(self.value)
                self._invalidate()
        elif key in ('right', 'l'):
            if self.value < self.max:
                self.value += 1
                self._w = self._build()
                self.on_change(self.value)
                self._invalidate()
        else:
            return key
    def selectable(self):
        return True

# Menu navigation stack
menu_stack = []

def open_menu(menu):
    menu_stack.append(menu)
    main.original_widget = urwid.LineBox(menu_stack[-1])

def back_menu(button=None):
    if len(menu_stack) > 1:
        menu_stack.pop()
        main.original_widget = urwid.LineBox(menu_stack[-1])

# Display Settings Menu
def display_settings_menu():
    brightness = [50]
    contrast = [50]
    def on_brightness_change(val):
        brightness[0] = val
        lcd.set_brightness(val)
    def on_contrast_change(val):
        contrast[0] = val
        lcd.set_contrast(val)
    items = [
        urwid.Text("Adjust Display Settings"),
        urwid.Divider(),
        CustomSlider("Brightness", 0, 100, brightness[0], on_brightness_change),
        CustomSlider("Contrast", 0, 100, contrast[0], on_contrast_change),
        urwid.Divider(),
        back_button(back_menu)
    ]
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# Cursor Settings Menu
def cursor_settings_menu():
    styles = ["None", "Underline", "Block", "Blink"]
    selected = [styles[0]]
    def on_select(style):
        selected[0] = style
        lcd.set_cursor_style(style)
        open_menu(cursor_settings_menu())
    items = [urwid.Text("Cursor Style"), urwid.Divider()]
    for style in styles:
        items.append(custom_radio(style, styles, selected[0] == style, on_select))
    items.append(urwid.Divider())
    items.append(back_button(back_menu))
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# LED Settings Menu
def led_settings_menu():
    leds = ["LED1", "LED2", "LED3", "LED4"]
    colors = ["Off", "Red", "Green", "Blue", "Yellow", "White"]
    led_states = {led: "Off" for led in leds}
    def on_led_change(led, color):
        led_states[led] = color
        lcd.set_led_color(led, color)
        open_menu(led_settings_menu())
    items = [urwid.Text("LED Settings"), urwid.Divider()]
    for led in leds:
        items.append(urwid.Text(led))
        for color in colors:
            items.append(custom_radio(
                color,
                colors,
                led_states[led] == color,
                lambda c, led=led: on_led_change(led, c)
            ))
        items.append(urwid.Divider())
    items.append(back_button(back_menu))
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# About Menu
def about_menu():
    text = (
        "Crystalfontz 635 LCD Demo\n"
        "This demo shows a menu-driven UI for adjusting display, cursor, and LED settings.\n"
        "Custom characters are used for checkboxes, radio buttons, progress bars, and sliders.\n"
        "Use arrow keys to navigate. Press 'q' or 'esc' to go back."
    )
    items = [
        urwid.Text(text),
        urwid.Divider(),
        back_button(back_menu)
    ]
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

# Main Menu
def main_menu():
    items = [
        urwid.Text("Crystalfontz 635 LCD Demo"),
        urwid.Divider(),
        menu_button("Display Settings", lambda btn: open_menu(display_settings_menu())),
        menu_button("Cursor Settings", lambda btn: open_menu(cursor_settings_menu())),
        menu_button("LED Settings", lambda btn: open_menu(led_settings_menu())),
        menu_button("About this Demo", lambda btn: open_menu(about_menu())),
        urwid.Divider(),
        urwid.Text("Progress:"),
        custom_progress_bar(60, 100, 16),
        urwid.Divider(),
        urwid.Text("Slider:"),
        CustomSlider("Value", 0, 100, 40, lambda v: None),
    ]
    return urwid.ListBox(urwid.SimpleFocusListWalker(items))

main = urwid.Padding(urwid.LineBox(main_menu()), left=2, right=2)
menu_stack.append(main_menu())

def unhandled_input(key):
    if key in ('esc', 'q'):
        back_menu()
    elif key in ('ctrl c',):
        raise urwid.ExitMainLoop()

